ALTER TABLE "transport_routes" ADD COLUMN "fee_structure_id" UUID;
ALTER TABLE "transport_routes" ADD CONSTRAINT "transport_routes_fee_structure_id_fkey" FOREIGN KEY("fee_structure_id") REFERENCES "fee_structures"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "transport_enrollments" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"route_id" UUID NOT NULL,"enrollment_id" UUID NOT NULL,"student_fee_assignment_id" UUID,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "transport_enrollments_pkey" PRIMARY KEY("id"),CONSTRAINT "transport_enrollments_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "transport_enrollments_route_id_fkey" FOREIGN KEY("route_id") REFERENCES "transport_routes"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "transport_enrollments_enrollment_id_fkey" FOREIGN KEY("enrollment_id") REFERENCES "enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "transport_enrollments_student_fee_assignment_id_fkey" FOREIGN KEY("student_fee_assignment_id") REFERENCES "student_fee_assignments"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "transport_enrollments_route_id_enrollment_id_key" ON "transport_enrollments"("route_id","enrollment_id");
CREATE UNIQUE INDEX "transport_enrollments_student_fee_assignment_id_key" ON "transport_enrollments"("student_fee_assignment_id");
CREATE INDEX "transport_enrollments_school_id_enrollment_id_idx" ON "transport_enrollments"("school_id","enrollment_id");
